    # 1. Check unknown depots and roads
    for i, stop in enumerate(stops):
        if stop not in adj:
            errors.append(f"unknown depot {stop}")
        elif i > 0:
            # Check road from previous stop to current stop
            prev_stop = stops[i-1]
            # Note: if prev_stop was unknown, we already added it to errors.
            # However, the spec says "for each stop the unknown-depot check comes first, 
            # then (from the second stop on) the road check for the leg arriving at it."
            # If prev_stop is unknown, adj[prev_stop] will raise KeyError.
            # Let's check if prev_stop is in adj before accessing.
            if prev_stop in adj and stop not in adj[prev_stop]:
                errors.append(f"no road {prev_stop}-{stop}")

    # 2. Check max legs
    if max_legs is not None:
        num_legs = len(stops) - 1
        if num_legs > max_legs:
            errors.append(f"too many legs: {num_legs} > {max_legs}")

